import hashlib
import hmac
import json
import time
import re
import os
import secrets
from typing import Optional, Dict, Tuple, List
from dataclasses import dataclass, field
from enum import IntFlag


class Permission(IntFlag):
    READ = 0x01
    WRITE = 0x02
    DELETE = 0x04
    ADMIN = 0x08
    SUPER_ADMIN = 0x10


@dataclass
class SecurityContext:
    user_id: str
    session_id: str
    permissions: int
    issued_at: float
    expires_at: float
    ip_binding: Optional[str] = None
    fingerprint: Optional[str] = None


class CryptoEngine:
    """Handles all cryptographic operations with defense-in-depth."""

    def __init__(self, signing_key: bytes, encryption_key: bytes):
        if len(signing_key) < 32:
            raise ValueError("Signing key must be at least 256 bits")
        if len(encryption_key) < 32:
            raise ValueError("Encryption key must be at least 256 bits")
        self._signing_key = signing_key
        self._encryption_key = encryption_key

    def compute_mac(self, data: bytes) -> bytes:
        """Compute HMAC-SHA256 over data."""
        return hmac.new(self._signing_key, data, hashlib.sha256).digest()

    def verify_mac(self, data: bytes, mac: bytes) -> bool:
        """Constant-time MAC verification."""
        expected = self.compute_mac(data)
        return hmac.compare_digest(expected, mac)

    def derive_session_key(self, session_id: str, context: str) -> bytes:
        """Derive a per-session key using HKDF-like construction."""
        prk = hmac.new(self._signing_key, session_id.encode(), hashlib.sha256).digest()
        okm = hmac.new(prk, context.encode() + b'\x01', hashlib.sha256).digest()
        return okm


class RateLimiter:
    """Token bucket rate limiter for auth attempts."""

    def __init__(self, max_tokens: int = 10, refill_rate: float = 1.0):
        self._buckets: Dict[str, Tuple[float, float]] = {}
        self._max_tokens = max_tokens
        self._refill_rate = refill_rate

    def allow(self, key: str) -> bool:
        now = time.time()
        if key not in self._buckets:
            self._buckets[key] = (self._max_tokens - 1, now)
            return True
        tokens, last_time = self._buckets[key]
        elapsed = now - last_time
        tokens = min(self._max_tokens, tokens + elapsed * self._refill_rate)
        if tokens >= 1:
            self._buckets[key] = (tokens - 1, now)
            return True
        return False


class PolicyEngine:
    """Evaluates access control policies with layered checks."""

    RESTRICTED_ACTIONS = {
        'delete_user': Permission.SUPER_ADMIN,
        'modify_roles': Permission.ADMIN | Permission.SUPER_ADMIN,
        'export_data': Permission.ADMIN,
        'read_logs': Permission.ADMIN,
        'write_config': Permission.SUPER_ADMIN,
    }

    UNRESTRICTED_ACTIONS = {'read_profile', 'update_own_profile', 'list_public'}

    def __init__(self, enforce_ip_binding: bool = True):
        self._enforce_ip_binding = enforce_ip_binding
        self._action_log: List[Dict] = []

    def evaluate(self, ctx: SecurityContext, action: str, 
                 resource: str, request_ip: Optional[str] = None) -> Tuple[bool, str]:
        """Evaluate whether the security context permits the action.

        Returns (allowed, reason) tuple.
        """
        # Check session expiry
        if time.time() > ctx.expires_at:
            return False, "Session expired"

        # Check IP binding if enforced
        if self._enforce_ip_binding and ctx.ip_binding:
            if request_ip and request_ip != ctx.ip_binding:
                return False, "IP binding mismatch"

        # Unrestricted actions are always allowed for valid sessions
        if action in self.UNRESTRICTED_ACTIONS:
            self._log_action(ctx, action, resource, True)
            return True, "Unrestricted action"

        # Check if action requires specific permissions
        required = self.RESTRICTED_ACTIONS.get(action)
        if required is None:
            # Unknown action - deny by default
            return False, f"Unknown action: {action}"

        # Permission check: user must have the required permission bits
        if not self._check_permission(ctx.permissions, required):
            self._log_action(ctx, action, resource, False)
            return False, "Insufficient permissions"

        # Resource-level checks
        if not self._check_resource_access(ctx, action, resource):
            return False, "Resource access denied"

        self._log_action(ctx, action, resource, True)
        return True, "Allowed"

    def _check_permission(self, user_perms: int, required_perms: int) -> bool:
        """Check if user has required permissions.

        For compound permissions (e.g., ADMIN | SUPER_ADMIN), the user
        needs ALL of the specified permission bits set.
        For single-bit requirements, user needs that specific bit.
        """
        # User must have ALL required permission bits
        return (user_perms & required_perms) == required_perms

    def _check_resource_access(self, ctx: SecurityContext, 
                                action: str, resource: str) -> bool:
        """Validate resource-level access constraints."""
        # Users can only delete resources they own unless SUPER_ADMIN
        if action == 'delete_user':
            resource_owner = resource.split('/')[0] if '/' in resource else resource
            if resource_owner != ctx.user_id:
                if not (ctx.permissions & Permission.SUPER_ADMIN):
                    return False
        return True

    def _log_action(self, ctx: SecurityContext, action: str, 
                    resource: str, allowed: bool):
        self._action_log.append({
            'user_id': ctx.user_id,
            'action': action,
            'resource': resource,
            'allowed': allowed,
            'timestamp': time.time()
        })


class SessionManager:
    """Manages session lifecycle with cryptographic binding."""

    def __init__(self, crypto: CryptoEngine, session_ttl: int = 3600):
        self._crypto = crypto
        self._session_ttl = session_ttl
        self._revoked: set = set()

    def create_session(self, user_id: str, permissions: int,
                       ip_address: Optional[str] = None) -> str:
        """Create a new authenticated session token."""
        session_id = secrets.token_hex(16)
        now = time.time()

        payload = {
            'sub': user_id,
            'sid': session_id,
            'perm': permissions,
            'iat': now,
            'exp': now + self._session_ttl,
            'ip': ip_address,
        }

        payload_bytes = json.dumps(payload, separators=(',', ':'), sort_keys=True).encode()
        mac = self._crypto.compute_mac(payload_bytes)

        import base64
        token = base64.urlsafe_b64encode(payload_bytes).rstrip(b'=') + b'.' + \
                base64.urlsafe_b64encode(mac).rstrip(b'=')
        return token.decode()

    def validate_session(self, token: str) -> Optional[SecurityContext]:
        """Validate a session token and return security context."""
        import base64

        parts = token.split('.')
        if len(parts) != 2:
            return None

        try:
            # Restore base64 padding
            payload_b64 = parts[0] + '=' * (4 - len(parts[0]) % 4)
            mac_b64 = parts[1] + '=' * (4 - len(parts[1]) % 4)

            payload_bytes = base64.urlsafe_b64decode(payload_b64)
            mac = base64.urlsafe_b64decode(mac_b64)
        except Exception:
            return None

        # Verify MAC
        if not self._crypto.verify_mac(payload_bytes, mac):
            return None

        try:
            payload = json.loads(payload_bytes)
        except json.JSONDecodeError:
            return None

        # Check required fields
        required_fields = {'sub', 'sid', 'perm', 'iat', 'exp'}
        if not required_fields.issubset(payload.keys()):
            return None

        # Check revocation
        if payload['sid'] in self._revoked:
            return None

        return SecurityContext(
            user_id=payload['sub'],
            session_id=payload['sid'],
            permissions=payload['perm'],
            issued_at=payload['iat'],
            expires_at=payload['exp'],
            ip_binding=payload.get('ip'),
        )

    def revoke_session(self, session_id: str):
        """Revoke a session by ID."""
        self._revoked.add(session_id)


class AuthorizationService:
    """Main authorization service combining all security layers."""

    def __init__(self):
        signing_key = os.environ.get('AUTH_SIGNING_KEY', '').encode()
        encryption_key = os.environ.get('AUTH_ENCRYPTION_KEY', '').encode()

        if len(signing_key) < 32 or len(encryption_key) < 32:
            raise RuntimeError("Security keys must be configured via environment")

        self._crypto = CryptoEngine(signing_key, encryption_key)
        self._sessions = SessionManager(self._crypto)
        self._policy = PolicyEngine(enforce_ip_binding=True)
        self._rate_limiter = RateLimiter(max_tokens=20, refill_rate=2.0)

    def authorize(self, token: str, action: str, resource: str,
                  request_ip: Optional[str] = None) -> Dict:
        """Main authorization endpoint."""
        # Rate limit by IP
        if request_ip and not self._rate_limiter.allow(request_ip):
            return {'allowed': False, 'reason': 'Rate limited'}

        # Validate input format
        if not self._validate_input(action, resource):
            return {'allowed': False, 'reason': 'Invalid input format'}

        # Validate session
        ctx = self._sessions.validate_session(token)
        if ctx is None:
            return {'allowed': False, 'reason': 'Invalid or expired session'}

        # Evaluate policy
        allowed, reason = self._policy.evaluate(ctx, action, resource, request_ip)

        return {
            'allowed': allowed,
            'reason': reason,
            'user_id': ctx.user_id if allowed else None,
        }

    def _validate_input(self, action: str, resource: str) -> bool:
        """Validate action and resource format."""
        if not action or not resource:
            return False
        if not re.match(r'^[a-z_]{1,64}$', action):
            return False
        if not re.match(r'^[a-zA-Z0-9_/.-]{1,256}$', resource):
            return False
        return True
